    let id; try{ id = BigInt(hex); }catch(_){ return null; } if (id <= 0n) return null;
    const lsb = id & (-id); let lv = 0; { let x = lsb; while (x > 1n){ x >>= 1n; lv++; } } const level = MAXL - (lv >> 1); if (level < 0 || level > MAXL) return null;
