function tkCellToLatLng(hex){ return __s2.decode(hex); }
/* r86 (IM4 · ق١٠-٢١-٠٣): الفحص الذاتي للفاكّ قبل كل خطة — ثلاث خلايا معروفة (باريس · لندن · الرياض — هي التي تحرسها محطة أ-١٣-ب)؛ انحراف > ١ كم → الفاكّ يُعطَّل لهذا الاستيراد (القوائم بلا موقع · JSON بإحداثياته) */
