  if ((last.towns || []).length){ L.push(''); L.push('Towns you saved as destinations — not imported (' + last.towns.length + '): ' + last.towns.join(' · ')); } if ((last.removedBefore || []).length){ L.push(''); L.push('Places you removed before — not imported (' + last.removedBefore.length + '): ' + last.removedBefore.join(' · ')); } /* r86-3 */ if ((last.smallOff || []).length){ L.push(''); L.push('Small new cities left unticked (' + last.smallOff.length + '): ' + last.smallOff.join(' · ')); } if ((last.autoMerged || []).length){ L.push(''); L.push('Small new cities tucked under the city next door (' + last.autoMerged.length + '): ' + last.autoMerged.join(' · ')); } /* r86-1 */
